    en: 'English',
    ar: 'Arabic',
    zh: 'Chinese',
    fr: 'French',
    de: 'German',
    hi: 'Hindi',
    ja: 'Japanese',
    ko: 'Korean',
    pt: 'Portuguese',
    es: 'Spanish',
