      '  inset: 0;',
      '  pointer-events: none;',
      '  z-index: 2;',
      '  background: linear-gradient(',
      '    to bottom,',
      '    rgba(255,255,255,0.35) 0%,',
      '    transparent 12%,',
      '    transparent 88%,',
      '    rgba(255,255,255,0.35) 100%',
      '  );',
      '}',
